//! Emojis (`/emoji coeur`) and special characters (`/car tiret`), searched in French and English.
//! Emoji names come from emojibase (data/emoji.tsv, regenerated by scripts/emoji-data.py).

use crate::engine::Outcome;
use crate::i18n::{english, t, tf};
use crate::search::{fold, Action, Item};
use std::sync::LazyLock;

struct Entry {
    text: String,
    /// Name and keywords in the interface language first, then in the other one.
    name: [String; 2],
    keywords: [Vec<String>; 2],
}

static EMOJIS: LazyLock<Vec<Entry>> = LazyLock::new(|| {
    include_str!("../../data/emoji.tsv")
        .lines()
        .filter_map(|l| {
            let f: Vec<&str> = l.split('\t').collect();
            let words = |s: &str| s.split(',').filter(|w| !w.is_empty()).map(String::from).collect();
            Some(Entry { text: f.first()?.to_string(), name: [f.get(2)?.to_string(), f.get(4)?.to_string()], keywords: [words(f.get(3)?), words(f.get(5)?)] })
        })
        .collect()
});

