/// Score of an entry for the query words: every word must match, the name counts more than the
/// keywords and the interface language more than the other one. None when a word is missing.
fn score(words: &[String], name: &[String; 2], keywords: &[Vec<String>; 2]) -> Option<u32> {
    let mut total = 0;
    for w in words {
        let mut best = 0;
        for lang in 0..2 {
            let weight = if lang == 0 { 2 } else { 1 };
            let n = fold(&name[lang]);
            if n.split([' ', '-']).any(|p| p.starts_with(w.as_str())) {
                best = best.max(30 * weight);
            } else if n.contains(w.as_str()) {
                best = best.max(15 * weight);
            }
            for k in &keywords[lang] {
                let k = fold(k);
                if k == *w {
                    best = best.max(20 * weight);
                } else if k.starts_with(w.as_str()) {
                    best = best.max(10 * weight);
                }
            }
        }
        if best == 0 {
            return None;
        }
        total += best;
    }
    Some(total)
}

fn split(q: &str) -> Vec<String> {
    fold(q).split_whitespace().map(String::from).collect()
}

fn item(prefix: &str, text: &str, title: String, subtitle: String) -> Item {
    let code: Vec<String> = text.chars().map(|c| format!("U+{:04X}", c as u32)).collect();
    Item {
        id: format!("{prefix}:{}", code.join("-")),
        module: "emoji".into(),
        title,
        subtitle,
        actions: vec![Action::new("paste", "Coller"), Action::new("copy", "Copier"), Action::new("copy-code", "Copier le code")],
        data: format!("{}\t{text}", code.join(" ")),
        ..Default::default()
    }
}

/// `/emoji coeur rouge`: best matches first, in the emoji order when nothing is typed.
pub fn emojis(query: &str, limit: usize) -> Vec<Item> {
    let lang = usize::from(english());
    let words = split(query);
    let mut found: Vec<(u32, usize, &Entry)> = EMOJIS
        .iter()
        .enumerate()
        .filter_map(|(i, e)| {
            let name = [e.name[lang].clone(), e.name[1 - lang].clone()];
            let kw = [e.keywords[lang].clone(), e.keywords[1 - lang].clone()];
            score(&words, &name, &kw).map(|s| (s, i, e))
        })
        .collect();
    found.sort_by(|a, b| b.0.cmp(&a.0).then(a.1.cmp(&b.1)));
    found
        .into_iter()
        .take(limit)
        .map(|(_, _, e)| item("emoji", &e.text, format!("{}  {}", e.text, e.name[lang]), e.keywords[lang].iter().take(6).cloned().collect::<Vec<_>>().join(", ")))
        .collect()
}

/// `/car tiret`: special characters, invisible ones shown with their name.
pub fn chars(query: &str, limit: usize) -> Vec<Item> {
    let words = split(query);
    let mut found: Vec<(u32, usize, &(&str, &str, &str))> = CHARS
        .iter()
        .enumerate()
        .filter_map(|(i, c)| {
            let kw: Vec<String> = c.2.split_whitespace().map(String::from).collect();
            score(&words, &[t(c.1), c.1.to_string()], &[kw.clone(), kw]).map(|s| (s, i, c))
        })
        .collect();
    found.sort_by(|a, b| b.0.cmp(&a.0).then(a.1.cmp(&b.1)));
    found
        .into_iter()
        .take(limit)
        .map(|(_, _, (ch, name, _))| {
            let shown = if ch.chars().all(char::is_whitespace) { format!("[{}]", t("espace")) } else { ch.to_string() };
            let code: Vec<String> = ch.chars().map(|c| format!("U+{:04X}", c as u32)).collect();
            item("char", ch, format!("{shown}  {}", t(name)), code.join(" "))
        })
        .collect()
}

pub fn run(item: &Item, action: &str) -> Result<Outcome, String> {
    let (code, text) = item.data.split_once('\t').unwrap_or(("", &item.data));
    Ok(match action {
        "paste" => Outcome::Paste { text: text.to_string(), back: 0 },
        "copy" => Outcome::Copy(text.to_string()),
        "copy-code" => Outcome::Copy(code.to_string()),
        _ => return Err(tf("action inconnue : {a}", &[("a", &action)])),
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn finds_emojis_in_french_and_english() {
        let r = emojis("coeur rouge", 5);
        assert!(r[0].title.starts_with('\u{2764}'), "{:?}", r.iter().map(|i| &i.title).collect::<Vec<_>>());
        assert!(!emojis("pizza", 3).is_empty());
        assert!(!emojis("grinning", 3).is_empty(), "les mots-clés anglais marchent aussi");
        assert!(emojis("zzzqqq", 5).is_empty());
        assert_eq!(emojis("", 8).len(), 8);
    }

    #[test]
    fn finds_special_characters() {
        let r = chars("tiret long", 3);
        assert_eq!(run(&r[0], "copy").unwrap(), Outcome::Copy("\u{2014}".into()));
        assert_eq!(run(&r[0], "copy-code").unwrap(), Outcome::Copy("U+2014".into()));
        assert!(chars("espace fine", 1)[0].title.starts_with("[espace]"));
        assert_eq!(chars("", 200).len(), CHARS.len());
    }
}
